// The rules the brief requires, as predicates over the spec's state.
const CLIENTS = ['c0', 'c1'];
const count = (net, prefix) => net.filter((m) => m.startsWith(prefix)).length;

export const stateInvariants = [
  {
    name: 'at-most-one-client-holds-the-current-token',
    pred: (s) => CLIENTS.filter((c) => s[`${c}Status`] === 'holding' && s[`${c}Token`] === s.token).length <= 1,
  },
  {
    name: 'quiescent-client-holds-iff-service-says-so',
    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => (s[`${c}Status`] === 'holding') === (s.holder === c)),
  },
  {
    name: 'quiescent-holder-has-the-current-token',
    pred: (s) => s.net.length > 0 || s.holder === null || s[`${s.holder}Token`] === s.token,
  },
  {
    name: 'service-holder-was-granted-the-current-token',
    pred: (s) => s.holder === null || s.token >= 1,
  },
  { name: 'at-most-2-grants', pred: (s) => s.token >= 0 && s.token <= 2 },
  { name: 'at-most-2-writes', pred: (s) => s.writes >= 0 && s.writes <= 2 },
  {
    name: 'writing-iff-write-or-answer-in-transit',
    pred: (s) => CLIENTS.every((c) => {
      const n = count(s.net, `Write|${c}|`) + count(s.net, `WriteDone|${c}|`) + count(s.net, `WriteRefused|${c}|`);
      return n === (s[`${c}Writing`] ? 1 : 0);
    }),
  },
  {
    name: 'requesting-iff-request-or-answer-in-transit',
    pred: (s) => CLIENTS.every((c) => {
      const n = count(s.net, `Acquire|${c}|`) + count(s.net, `Granted|${c}|`) + count(s.net, `Denied|${c}|`);
      return n === (s[`${c}Status`] === 'requesting' ? 1 : 0);
    }),
  },
];

export const transitionInvariants = [
  {
    name: 'writes-taken-only-from-the-holder-with-the-current-token',
    pred: (pre, action, data, post) => {
      if (post.writes === pre.writes) return true;
      if (action !== 'DELIVER' || post.writes !== pre.writes + 1) return false;
      const [name, client, token] = data.msg.split('|');
      return name === 'Write' && pre.holder === client && Number(token) === pre.token;
    },
  },
  {
    name: 'tokens-only-go-up',
    pred: (pre, _a, _d, post) => post.token >= pre.token && CLIENTS.every((c) => post[`${c}Token`] >= pre[`${c}Token`]),
  },
  {
    name: 'a-grant-goes-to-a-free-lease',
    pred: (pre, _a, _d, post) => post.token === pre.token || (pre.holder === null && post.token === pre.token + 1),
  },
];

