'use strict';
// SAM v2 strict-profile specification of src/host.impl.ts: the lease service,
// clients c0 and c1, and the network, as one state machine. A message in
// transit is the string "Name|client|token" (client = the client it comes from
// or goes to, token 0 when the message carries none); `net` is the sorted
// multiset of messages in transit, so delivery order is a free choice of the
// DELIVER intent.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CLIENTS = ['c0', 'c1'];
const MAX_GRANTS = 2;
const MAX_WRITES = 2;
const MESSAGES = ['Acquire', 'Release', 'Write', 'Granted', 'Denied', 'WriteDone', 'WriteRefused', 'Revoked'];

const INITIAL_STATE = {
  holder: null, token: 0, writes: 0,
  c0Status: 'idle', c0Token: 0, c0Writing: false, c0Revoked: 0,
  c1Status: 'idle', c1Token: 0, c1Writing: false, c1Revoked: 0,
  net: [],
};
const KEYS = Object.keys(INITIAL_STATE);

const msg = (name, client, token = 0) => `${name}|${client}|${token}`;
const add = (net, m) => [...net, m].sort();
const remove = (net, m) => { const i = net.indexOf(m); return [...net.slice(0, i), ...net.slice(i + 1)]; };
const others = (written) => KEYS.filter((k) => !written.includes(k));

const CLIENT_DOMAIN = [{ client: 'c0' }, { client: 'c1' }, { client: 'c9' }];
const DELIVER_DOMAIN = [];
for (const name of MESSAGES) for (const client of CLIENTS) for (const token of [0, 1, 2]) DELIVER_DOMAIN.push({ msg: msg(name, client, token) });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      holder: { type: ['string', 'null'] },
      token: { type: 'number' },
      writes: { type: 'number' },
      c0Status: { type: 'string' },
      c0Token: { type: 'number' },
      c0Writing: { type: 'boolean' },
      c0Revoked: { type: 'number' },
      c1Status: { type: 'string' },
      c1Token: { type: 'number' },
      c1Writing: { type: 'boolean' },
      c1Revoked: { type: 'number' },
      net: { type: 'array' },
    },
    actions: {
      ACQUIRE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      RELEASE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      WRITE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: { type: 'string', required: true } }, domain: DELIVER_DOMAIN },
    },
    acceptors: {
      ACQUIRE: (model) => ({ client }, { reject, next, unchanged }) => {
        if (!CLIENTS.includes(client)) return reject('unknown-client');
