        next.net = add(model.net, msg('Revoked', model.holder, model.token));
        unchanged(...others(['holder', 'net']));
      },
      DELIVER: (model) => ({ msg: m }, { reject, next, unchanged }) => {
        if (!model.net.includes(m)) return reject('not-in-flight');
        const [name, client, tokenText] = m.split('|');
        const token = Number(tokenText);
        const rest = remove(model.net, m);
        const S = `${client}Status`, T = `${client}Token`, W = `${client}Writing`, R = `${client}Revoked`;
        const written = ['net'];
