            } else if (token > model[R]) {
              next[R] = token; written.push(R);
            }
            break;
          case 'WriteDone':
          case 'WriteRefused':
            next.net = rest;
            next[W] = false; written.push(W);
            break;
        }
        unchanged(...others(written));
      },
    },
    reactors: [],
  },
});

