// Replay the captured trace corpus against the spec (polygraph's replay half).
// Usage: node spec/replay.mjs [spec-module]   (default spec/lease.spec.cjs)
import { loadWindows, replaySpec } from '../tools/polygraph/scripts/replay.mjs';

const here = (p) => new URL(p, import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const specPath = process.argv[2] ?? here('./lease.spec.cjs');
const windows = loadWindows(here('./traces'));
const statuses = replaySpec(specPath, windows);
const tally = {};
statuses.forEach((s, i) => {
  tally[s] = (tally[s] ?? 0) + 1;
  if (s !== 'pass' && (tally[s] ?? 0) <= 5) console.log(s, JSON.stringify(windows[i]));
});
console.log(`${windows.length} windows:`, tally);
process.exit(Object.keys(tally).every((s) => s === 'pass') ? 0 : 1);

