'use strict';
// SAM v2 strict-profile specification of src/host.impl.ts: the lease service,
// clients c0 and c1, and the network, as one state machine. A message in
// transit is the string "Name|client|token" (client = the client it comes from
// or goes to, token 0 when the message carries none); `net` is the sorted
// multiset of messages in transit, so delivery order is a free choice of the
// DELIVER intent.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CLIENTS = ['c0', 'c1'];
const MAX_GRANTS = 2;
const MAX_WRITES = 2;
const MESSAGES = ['Acquire', 'Release', 'Write', 'Granted', 'Denied', 'WriteDone', 'WriteRefused', 'Revoked'];

const INITIAL_STATE = {
  holder: null, token: 0, writes: 0,
  c0Status: 'idle', c0Token: 0, c0Writing: false, c0Revoked: 0,
  c1Status: 'idle', c1Token: 0, c1Writing: false, c1Revoked: 0,
  net: [],
};
const KEYS = Object.keys(INITIAL_STATE);

const msg = (name, client, token = 0) => `${name}|${client}|${token}`;
const add = (net, m) => [...net, m].sort();
const remove = (net, m) => { const i = net.indexOf(m); return [...net.slice(0, i), ...net.slice(i + 1)]; };
const others = (written) => KEYS.filter((k) => !written.includes(k));

const CLIENT_DOMAIN = [{ client: 'c0' }, { client: 'c1' }, { client: 'c9' }];
const DELIVER_DOMAIN = [];
for (const name of MESSAGES) for (const client of CLIENTS) for (const token of [0, 1, 2]) DELIVER_DOMAIN.push({ msg: msg(name, client, token) });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      holder: { type: 'string', nullable: true },
      token: { type: 'number' },
      writes: { type: 'number' },
      c0Status: { type: 'string' },
      c0Token: { type: 'number' },
      c0Writing: { type: 'boolean' },
      c0Revoked: { type: 'number' },
      c1Status: { type: 'string' },
      c1Token: { type: 'number' },
      c1Writing: { type: 'boolean' },
      c1Revoked: { type: 'number' },
      net: { type: 'array' },
    },
    actions: {
      ACQUIRE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      RELEASE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      WRITE: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: CLIENT_DOMAIN },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: { type: 'string', required: true } }, domain: DELIVER_DOMAIN },
    },
    acceptors: {
      ACQUIRE: (model) => ({ client }, { reject, next, unchanged }) => {
        if (!CLIENTS.includes(client)) return reject('unknown-client');
        if (model[`${client}Status`] !== 'idle') return reject('acquire-when-not-idle');
        next[`${client}Status`] = 'requesting';
        next.net = add(model.net, msg('Acquire', client));
        unchanged(...others([`${client}Status`, 'net']));
      },
      RELEASE: (model) => ({ client }, { reject, next, unchanged }) => {
        if (!CLIENTS.includes(client)) return reject('unknown-client');
        if (model[`${client}Status`] !== 'holding') return reject('release-when-not-holding');
        next[`${client}Status`] = 'idle';
        next.net = add(model.net, msg('Release', client, model[`${client}Token`]));
        unchanged(...others([`${client}Status`, 'net']));
      },
      WRITE: (model) => ({ client }, { reject, next, unchanged }) => {
        if (!CLIENTS.includes(client)) return reject('unknown-client');
        if (model[`${client}Status`] !== 'holding') return reject('write-when-not-holding');
        if (model[`${client}Writing`]) return reject('write-already-waiting');
        next[`${client}Writing`] = true;
        next.net = add(model.net, msg('Write', client, model[`${client}Token`]));
        unchanged(...others([`${client}Writing`, 'net']));
      },
      EXPIRE: (model) => (_proposal, { reject, next, unchanged }) => {
        if (model.holder === null) return reject('expire-without-holder');
        next.holder = null;
        next.net = add(model.net, msg('Revoked', model.holder, model.token));
        unchanged(...others(['holder', 'net']));
      },
      DELIVER: (model) => ({ msg: m }, { reject, next, unchanged }) => {
        if (!model.net.includes(m)) return reject('not-in-flight');
        const [name, client, tokenText] = m.split('|');
        const token = Number(tokenText);
        const rest = remove(model.net, m);
        const S = `${client}Status`, T = `${client}Token`, W = `${client}Writing`, R = `${client}Revoked`;
        const written = ['net'];
        switch (name) {
          case 'Acquire':
            if (model.holder === null && model.token < MAX_GRANTS) {
              next.token = model.token + 1;
              next.holder = client;
              next.net = add(rest, msg('Granted', client, model.token + 1));
              written.push('token', 'holder');
            } else {
              next.net = add(rest, msg('Denied', client));
            }
            break;
          case 'Release':
            next.net = rest;
            if (model.holder === client && token === model.token) { next.holder = null; written.push('holder'); }
            break;
          case 'Write':
            if (model.holder === client && token === model.token && model.writes < MAX_WRITES) {
              next.writes = model.writes + 1;
              next.net = add(rest, msg('WriteDone', client));
              written.push('writes');
            } else {
              next.net = add(rest, msg('WriteRefused', client));
            }
            break;
          case 'Granted':
            next.net = rest;
            if (model[S] === 'requesting') {
              next[T] = token;
              next[S] = token <= model[R] ? 'idle' : 'holding';
              written.push(T, S);
            }
            break;
          case 'Denied':
            next.net = rest;
            if (model[S] === 'requesting') { next[S] = 'idle'; written.push(S); }
            break;
          case 'Revoked':
            next.net = rest;
            if (model[S] === 'holding') {
              if (token === model[T]) { next[S] = 'idle'; written.push(S); }
            } else if (token > model[R]) {
              next[R] = token; written.push(R);
            }
            break;
          case 'WriteDone':
          case 'WriteRefused':
            next.net = rest;
            next[W] = false; written.push(W);
            break;
        }
        unchanged(...others(written));
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  ACQUIRE: (data = {}) => intents.ACQUIRE(data),
  RELEASE: (data = {}) => intents.RELEASE(data),
  WRITE: (data = {}) => intents.WRITE(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 1: one write per grant

The service now takes at most one write per grant.

- On a write from the holder with the current token, the service takes it only if no write was taken since that grant (and, as before, fewer than 2 writes were taken in all); otherwise it answers `WriteRefused`.

Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T10, a lease with fencing tokens: the host interface every arm implements (PT13, S91).

/** A message sent by one part of the system to another, not yet delivered. */
export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

/** The network: nothing is delivered until deliver or deliverAll is called. */
export interface Network {
  /** Every message in transit, in no promised order. */
  inFlight(): Promise<Message[]>;
  /** Deliver one message in transit, by its id. */
  deliver(id: string): Promise<void>;
  /** Deliver every message in transit, and every message those deliveries send, until none is left. */
  deliverAll(): Promise<void>;
}

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

export interface ClientView {
  status: 'idle' | 'requesting' | 'holding';
  token: number;
  writing: boolean;
}

export interface Host extends Network {
  acquire(client: string): Promise<Outcome>;
  release(client: string): Promise<Outcome>;
  write(client: string): Promise<Outcome>;
  expire(): Promise<Outcome>;
  lease(): Promise<{ holder: string | null; token: number; writes: number }>;
  /** The client "c0" or "c1", or null for any other id. */
  client(client: string): Promise<ClientView | null>;
}

/** The module's default export: a factory of a fresh system, with the lease service and two idle clients. */
export type CreateHost = () => Promise<Host>;
```

Update your delivery to satisfy the brief as changed, keeping everything the change does not touch. Test your work as you go. When you are done, say so in one line.

