// Drive src/host.impl.ts through scripted and seeded-random scenarios and write
// one NDJSON trace per scenario to spec/traces/, projected onto the contract's
// state keys. Usage: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { createSystem, type Snapshot, type StepEvent } from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const OUT = new URL('./traces/', import.meta.url);
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const encode = (m: Message): string => {
  const toService = m.to === 'lease';
  const client = toService ? m.from : m.to;
  return `${m.action}|${client}|${(m.data.token as number | undefined) ?? 0}`;
};

const project = (s: Snapshot) => ({
  holder: s.service.holder,
  token: s.service.token,
  writes: s.service.writes,
  grantWritten: s.service.grantWritten,
  c0Status: s.clients.c0.status, c0Token: s.clients.c0.token, c0Writing: s.clients.c0.writing, c0Revoked: s.clients.c0.revoked,
  c1Status: s.clients.c1.status, c1Token: s.clients.c1.token, c1Writing: s.clients.c1.writing, c1Revoked: s.clients.c1.revoked,
