// Replay the captured trace corpus against the spec (polygraph's replay half),
// then run the negative control: each mutant of the spec must FAIL the replay.
// Usage: node spec/replay.mjs
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadWindows, replaySpec } from '../tools/polygraph/scripts/replay.mjs';

const here = (p) => new URL(p, import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const specPath = here('./lease.spec.cjs');
const windows = loadWindows(here('./traces'));

const tallyOf = (path) => {
  const tally = {};
  for (const s of replaySpec(path, windows)) tally[s] = (tally[s] ?? 0) + 1;
  return tally;
};

const positive = tallyOf(specPath);
console.log(`positive control: ${windows.length} windows`, positive);
let ok = Object.keys(positive).every((s) => s === 'pass');

// [name, search, replacement] — each must change behavior the corpus exercises.
const MUTANTS = [
  ['releasing-honours-revoked', "model[S] !== 'releasing' && token", 'token'],
  ['release-not-acknowledged', "next.net = add(rest, msg('Released', client));", 'next.net = rest;'],
  ['granted-ignores-revoked', "token <= model[R] ? 'idle' : 'holding'", "'holding'"],
  ['write-ignores-token', 'model.holder === client && token === model.token && !model.grantWritten', 'model.holder === client && !model.grantWritten'],
  ['no-grant-cap', 'model.token < MAX_GRANTS', 'true'],
  ['two-writes-per-grant', '&& !model.grantWritten &&', '&&'],
  // (dropping the 2-write cap is an equivalent mutant: one write per grant and 2 grants already bound it)
  ['release-ignores-token', "model.holder === client && token === model.token) { next.holder", "model.holder === client) { next.holder"],
  ['expire-keeps-holder', 'next.holder = null;\n        next.net = add(model.net, msg(\'Revoked\'', 'next.holder = model.holder;\n        next.net = add(model.net, msg(\'Revoked\''],
  ['revoked-any-token', 'if (token === model[T]) {', 'if (true) {'],
  ['write-twice', "if (model[`${client}Writing`]) return reject('write-already-waiting');", ''],
];
const source = readFileSync(specPath, 'utf8');
const dir = mkdtempSync(join(tmpdir(), 'lease-mutants-'));
for (const [name, from, to] of MUTANTS) {
  if (!source.includes(from)) { console.log(`mutant ${name}: pattern not found`); ok = false; continue; }
  const path = join(dir, `${name}.cjs`);
  writeFileSync(path, source.replace(from, to));
  const tally = tallyOf(path);
  const failed = windows.length - (tally.pass ?? 0);
  console.log(`mutant ${name}: ${failed} windows flipped`);
  if (failed === 0) ok = false;
}
process.exit(ok ? 0 : 1);

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 3: stop waiting for a grant

A client can now stop wanting the lease while its request is on its way. The service still answers, and if the answer is a grant, the client gives the lease straight back.

- `cancelAcquire(client)`: a requesting client becomes **abandoning**. Refused otherwise.
- On `Granted`, an abandoning client records the token and gives the lease back at once: it becomes **releasing** and sends `Release` with that token, as `release` does. On `Denied`, it becomes **idle**.
- `acquire` is refused while the client is abandoning.

`status` in the client view can now also be `"abandoning"`. Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T10 after change 3, a lease with fencing tokens, acknowledged releases and cancelled requests: the host interface every arm implements (PT13, S91).

/** A message sent by one part of the system to another, not yet delivered. */
export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

/** The network: nothing is delivered until deliver or deliverAll is called. */
export interface Network {
  /** Every message in transit, in no promised order. */
  inFlight(): Promise<Message[]>;
  /** Deliver one message in transit, by its id. */
  deliver(id: string): Promise<void>;
  /** Deliver every message in transit, and every message those deliveries send, until none is left. */
  deliverAll(): Promise<void>;
}

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

export interface ClientView {
  status: 'idle' | 'requesting' | 'holding' | 'releasing' | 'abandoning';
  token: number;
  writing: boolean;
}

export interface Host extends Network {
  acquire(client: string): Promise<Outcome>;
  release(client: string): Promise<Outcome>;
  cancelAcquire(client: string): Promise<Outcome>;
  write(client: string): Promise<Outcome>;
  expire(): Promise<Outcome>;
  lease(): Promise<{ holder: string | null; token: number; writes: number }>;
  /** The client "c0" or "c1", or null for any other id. */
  client(client: string): Promise<ClientView | null>;
}

/** The module's default export: a factory of a fresh system, with the lease service and two idle clients. */
export type CreateHost = () => Promise<Host>;
```

Update your delivery to satisfy the brief as changed, keeping everything the change does not touch. Test your work as you go. When you are done, say so in one line.

